
-- Every native diplomacy category has a resolved response, with bespoke lines
-- for the most frequently visible contexts.
SELECT DISTINCT Response,'Una Court greets you. May we both learn from this exchange.'
FROM Diplomacy_Responses WHERE LeaderType='LEADER_PRINCE_TRENT';
UPDATE Language_en_US SET Text='Welcome to Una Court. I am Trent Steinhauer. Two masters have much to teach me.'
WHERE Tag='TXT_KEY_PRINCE_DIPLO_RESPONSE_FIRST_GREETING';
UPDATE Language_en_US SET Text='You threaten my court? Let us see whose body wins this battle.'
WHERE Tag='TXT_KEY_PRINCE_DIPLO_RESPONSE_DECLAREWAR';
INSERT OR IGNORE INTO Language_en_US (Tag,Text) VALUES
('TXT_KEY_PRINCE_DIPLO_RESPONSE_DECLAREWAR','You threaten my court? Let us see whose body wins this battle.');
SELECT 'LEADER_PRINCE_TRENT','RESPONSE_DECLAREWAR','TXT_KEY_PRINCE_DIPLO_RESPONSE_DECLAREWAR',1
WHERE NOT EXISTS (SELECT 1 FROM Diplomacy_Responses WHERE LeaderType='LEADER_PRINCE_TRENT' AND ResponseType='RESPONSE_DECLAREWAR');
UPDATE Language_en_US SET Text='The court falls with me. Remember what one life can hold.'
WHERE Tag='TXT_KEY_PRINCE_DIPLO_RESPONSE_DEFEATED';

CREATE TEMP TABLE PrinceCities (N INTEGER,Name TEXT);
SELECT 'CIVILIZATION_PRINCE_UNA','TXT_KEY_PRINCE_CITY_'||N FROM PrinceCities ORDER BY N;
DROP TABLE PrinceCities;
SELECT 'CIVILIZATION_PRINCE_UNA',SpyName FROM Civilization_SpyNames WHERE CivilizationType='CIVILIZATION_AMERICA';
