INSERT INTO Language_en_US (Tag,Text) VALUES
('TXT_KEY_PRINCE_CIV','The Princedom of Una Court'),
('TXT_KEY_PRINCE_SHORT','Una Court (Two Masters)'),
('TXT_KEY_PRINCE_ADJECTIVE','Una Court'),
('TXT_KEY_PRINCE_LEADER','Trent Steinhauer — Pupil of Two Masters'),
('TXT_KEY_PRINCE_TRAIT','The Pupil of Two Masters'),
('TXT_KEY_PRINCE_TRAIT_HELP','Begin with one irreplaceable Trent Steinhauer, replacing your starting Warrior. Possess or Body Swap with an adjacent enemy land military unit, including Barbarians. Each successful technique earns one permanent stack in its own mastery, capped at 12. Mastery improves eligible target strength, duration and actual damage. Both techniques share a fixed game-speed cooldown. Fanfic Monuments double intrinsic benefits while either technique is active. If Trent''s original body dies, Una Court falls.'),
('TXT_KEY_PRINCE_STRATEGY','Keep Trent behind a protective line and practice on Barbarians. Each technique has its own mastery: alternate between them to develop both. Possession leaves an immobile, vulnerable original body; Body Swap gives that body to the enemy with substantial damage resistance and strict action limits. Stronger targets unlock at 3, 6, 9 and 12 stacks. Save the fixed shared cooldown for decisive engagements. Ordinary Warriors remain trainable as the Una Court militia.'),
('TXT_KEY_PRINCE_PEDIA','Una Court places its fate in the hands of one student. Trent studies possession under Baby of Dragon Ball GT and body exchange under Captain Ginyu of Dragon Ball Z. Practice strengthens each discipline independently, but no amount of mastery grants another life. Every Fanfic Monument celebrates these lessons, and flourishes while a technique is active.'),
('TXT_KEY_PRINCE_DAWN','One Trent. Two masters. Twenty-four potential mastery stacks. One life.'),
('TXT_KEY_PRINCE_LEADER_PEDIA','Trent Steinhauer, Prince of Una Court, admires Baby''s ability to possess another body and Captain Ginyu''s power to exchange bodies. His early attempts are brief and inefficient. Patient practice lets him command stronger bodies, but his original body remains the single point on which his realm depends.'),
('TXT_KEY_PRINCE_TRENT','Trent Steinhauer'),
('TXT_KEY_PRINCE_TRENT_HELP','Replaces the starting Warrior; 150% of its base strength and 2 Movement. Cannot be trained, purchased, gifted or disbanded. Normal upgrades preserve Trent''s identity, both masteries and shared cooldown. Cannot upgrade during a technique. Death of his original body eliminates Una Court, even while an enemy controls it.'),
('TXT_KEY_PRINCE_TRENT_STRATEGY','Trent begins at 12 Combat Strength when the installed Warrior has 8. Protect his original body, use the Two Masters panel against adjacent enemies, and upgrade normally between techniques. His borrowed bodies are expendable; his original body is not.'),
('TXT_KEY_PRINCE_TRENT_PEDIA','One irreplaceable practitioner carries the fate of Una Court. Promotions, experience, upgrades and mastery follow Trent throughout history. A borrowed body never becomes his original body and cannot pass on his techniques.'),
('TXT_KEY_PRINCE_FANFIC','Fanfic Monument'),
('TXT_KEY_PRINCE_FANFIC_HELP','Replaces the Monument and inherits its installed ruleset effects, cost and maintenance. Doubles intrinsic benefits in this city while Trent is actively possessing or body swapping. The bonus does not double maintenance or policy and religious modifiers.'),
('TXT_KEY_PRINCE_FANFIC_STRATEGY','Build Fanfic Monuments across Una Court. Their normal benefits double for the duration of either technique, returning immediately to baseline when Trent returns.'),
('TXT_KEY_PRINCE_FANFIC_PEDIA','Stories of possession and exchange fill the archives of Una Court. The Prince''s latest success inspires the authors to work twice as hard, until he returns to his original body and ordinary court life resumes.'),
('TXT_KEY_PRINCE_FANFIC_ACTIVE','Inspired Fanfic'),
('TXT_KEY_PRINCE_IDENTITY','One Life: Trent Steinhauer'),
('TXT_KEY_PRINCE_IDENTITY_HELP','Permanent original-body identity. Cannot be gifted or disbanded. If this body dies, Una Court is eliminated. Upgrades retain identity and mastery.'),
('TXT_KEY_PRINCE_BORROWED','Borrowed Body'),
('TXT_KEY_PRINCE_BORROWED_HELP','Temporary controller. Retains current health, experience and promotions on return. Cannot upgrade, embark, be gifted or disbanded. Cannot initiate another technique.'),
('TXT_KEY_PRINCE_SHELL','Trent''s Original Body'),
('TXT_KEY_PRINCE_SHELL_HELP','During possession: immobilized. During Body Swap: enemy-controlled, at most 1 Movement, no attacks, pillaging, embarking, upgrading, gifting, disbanding or city capture. Its death always destroys Una Court.'),
('TXT_KEY_PRINCE_RESIST','Body Swap Resistance'),
('TXT_KEY_PRINCE_RESIST_HELP','Reduces actual incoming combat damage by the resistance fixed at activation: 80%, 82%, 85%, 88% or 90%. Does not increase Combat Strength. The original body can still die.'),
('TXT_KEY_PRINCE_PANEL','Two Masters'),
('TXT_KEY_PRINCE_POSSESS','Possess'),
('TXT_KEY_PRINCE_SWAP','Body Swap'),
('TXT_KEY_PRINCE_UNLIMITED','Unlimited'),
('TXT_KEY_PRINCE_PROGRESS','{1_Technique}: {2_Num}/12 | Level {3_Num}[NEWLINE]{4_Num} turn(s), {5_Num}% damage, target strength {6_Text}'),
('TXT_KEY_PRINCE_RESISTANCE','Next Body Swap original-body resistance: {1_Num}%'),
('TXT_KEY_PRINCE_LOCKED_VALUES','Active borrowed damage: {1_Num}%; original-body resistance: {2_Num}%'),
('TXT_KEY_PRINCE_ACTIVE','{1_Technique} active: {2_Num} turn(s) remaining'),
('TXT_KEY_PRINCE_COOLDOWN','Shared cooldown: {1_Num} turn(s)'),
('TXT_KEY_PRINCE_CHOOSE_TECHNIQUE','Choose a technique to highlight eligible adjacent targets. Selecting a target activates it.'),
('TXT_KEY_PRINCE_CHOOSE_TARGET','Eligible targets are highlighted in violet. Select a unit below to activate.'),
('TXT_KEY_PRINCE_ACTIVATED','Trent''s technique is active for {1_Num} turn(s). Protect his original body!'),
('TXT_KEY_PRINCE_FALL','Trent''s original body has fallen. The Princedom of Una Court collapses.'),
('TXT_KEY_CIV5_PRINCE','The Princedom of Una Court'),
('TXT_KEY_CIV5_PRINCE_HEADING_1','Two Masters'),
('TXT_KEY_CIV5_PRINCE_TEXT_1','Baby teaches possession; Captain Ginyu teaches body exchange. Each successful activation grants one stack to that technique alone. Both counters permanently cap at 12, including after upgrades.'),
('TXT_KEY_CIV5_PRINCE_HEADING_2','Possession Mastery'),
('TXT_KEY_CIV5_PRINCE_TEXT_2','At 0/3/6/9/12 stacks, Standard duration is 1/1/2/2/3 turns and borrowed damage is -35/-20/-10/0/+10 percent. Trent''s original body stays immobile and receives normal damage. Losing the borrowed body ends possession safely.'),
('TXT_KEY_CIV5_PRINCE_HEADING_3','Body Swap Mastery'),
('TXT_KEY_CIV5_PRINCE_TEXT_3','At 0/3/6/9/12 stacks, Standard duration is 1/1/2/2/3 turns, original-body resistance is 80/82/85/88/90 percent, and borrowed damage is -20/0/+15/+25/+40 percent. The enemy controls the original body but cannot attack, pillage, embark, upgrade, disband, gift it or capture cities.'),
('TXT_KEY_CIV5_PRINCE_HEADING_4','Targets and Timing'),
('TXT_KEY_CIV5_PRINCE_TEXT_4','Targets must be adjacent, visible enemy land military units outside cities, including Barbarians. Neither body can already be involved in a technique. Target base strength, using the higher of melee and ranged values, is limited to 100/125/150/200 percent of Trent''s base strength at 0/3/6/9 stacks, and unlimited at 12. The successful activation uses the mastery before gaining its stack. Durations expire at the beginning of Trent''s player turn at activation turn plus duration.'),
('TXT_KEY_CIV5_PRINCE_HEADING_5','One Fixed Cooldown'),
('TXT_KEY_CIV5_PRINCE_TEXT_5','Quick/Standard/Epic/Marathon cooldowns are 5/8/12/24 turns. Duration multipliers are 0.67/1/1.5/3 with nearest-integer rounding and a minimum of one turn. Mastery never shortens cooldown. A fully mastered technique lasts 2/3/5/9 turns.'),
('TXT_KEY_CIV5_PRINCE_HEADING_6','The Fall of Una Court'),
('TXT_KEY_CIV5_PRINCE_TEXT_6','If Trent''s original body dies, the entire empire collapses. Normal upgrades transfer his identity; borrowing an enemy does not. Fanfic Monuments double their intrinsic benefits only while a technique is active. Protect the original body even at maximum mastery.'),
('TXT_KEY_CIV5_PRINCE_FACTOID_HEADING','The Student''s Oath'),
('TXT_KEY_CIV5_PRINCE_FACTOID_TEXT','One Trent. Two masters. One life.'),
('TXT_KEY_CIV5_PRINCE_LEADER','Trent Steinhauer'),
('TXT_KEY_CIV5_PRINCE_LEADER_HEADING_1','The Prince'),
('TXT_KEY_CIV5_PRINCE_LEADER_TEXT_1','Trent rules a court of ambitious authors and devoted students.'),
('TXT_KEY_CIV5_PRINCE_LEADER_HEADING_2','Baby''s Lesson'),
('TXT_KEY_CIV5_PRINCE_LEADER_TEXT_2','Possession turns a rival''s strength to Trent''s service while his own body waits helplessly.'),
('TXT_KEY_CIV5_PRINCE_LEADER_HEADING_3','Ginyu''s Lesson'),
('TXT_KEY_CIV5_PRINCE_LEADER_TEXT_3','Body exchange grants a rival temporary control of the Prince''s body. Resistance offers protection, never immortality.'),
('TXT_KEY_CIV5_PRINCE_LEADER_HEADING_4','Practice'),
('TXT_KEY_CIV5_PRINCE_LEADER_TEXT_4','Experience in one technique cannot substitute for practicing the other. Both disciplines demand twelve successes for complete mastery.'),
('TXT_KEY_CIVILOPEDIA_LEADERS_PRINCE_LEADER_NAME','Trent Steinhauer'),
('TXT_KEY_CIVILOPEDIA_LEADERS_PRINCE_LEADER_SUBTITLE','Pupil of Two Masters'),
('TXT_KEY_CIVILOPEDIA_LEADERS_PRINCE_LEADER_LIVED','The age of Una Court'),
('TXT_KEY_CIVILOPEDIA_LEADERS_PRINCE_LEADER_TITLES_1','Prince of Una Court');
